92	impl Resolved {
93	  /// Resolves the ACL for the given plugin permissions and app capabilities.
94	  pub fn resolve(
95	    acl: &BTreeMap<String, Manifest>,
96	    capabilities: BTreeMap<String, Capability>,
97	    target: Target,
98	  ) -> Result<Self, Error> {
99	    let mut allowed_commands = BTreeMap::new();
100	    let mut denied_commands = BTreeMap::new();
101	
102	    let mut current_scope_id = 0;
103	    let mut command_scopes = BTreeMap::new();
104	    let mut global_scope: BTreeMap<String, Vec<Scopes>> = BTreeMap::new();
105	
106	    // resolve commands
107	    for capability in capabilities.values() {
108	      if !capability.platforms.contains(&target) {
109	        continue;
110	      }
111	
112	      with_resolved_permissions(
113	        capability,
114	        acl,
115	        target,
116	        |ResolvedPermission {
117	           key,
118	           permission_name,
119	           commands,
120	           scope,
121	         }| {
122	          if commands.allow.is_empty() && commands.deny.is_empty() {
123	            // global scope
124	            global_scope.entry(key.to_string()).or_default().push(scope);
125	          } else {
126	            let scope_id = if scope.allow.is_some() || scope.deny.is_some() {
127	              current_scope_id += 1;
128	              command_scopes.insert(current_scope_id, scope);
129	              Some(current_scope_id)
130	            } else {
131	              None
132	            };
133	
134	            for allowed_command in &commands.allow {
135	              resolve_command(
136	                &mut allowed_commands,
137	                if key == APP_ACL_KEY {
138	                  allowed_command.to_string()
139	                } else {
140	                  format!("plugin:{key}|{allowed_command}")
141	                },
142	                capability,
143	                scope_id,
144	                #[cfg(debug_assertions)]
145	                permission_name.to_string(),
146	              );
147	            }
148	
149	            for denied_command in &commands.deny {
150	              resolve_command(
151	                &mut denied_commands,
152	                if key == APP_ACL_KEY {
153	                  denied_command.to_string()
154	                } else {
155	                  format!("plugin:{key}|{denied_command}")
156	                },
157	                capability,
158	                scope_id,
159	                #[cfg(debug_assertions)]
160	                permission_name.to_string(),
161	              );
162	            }
163	          }
164	        },
165	      )?;
166	    }
167	
168	    // resolve scopes
169	    let mut resolved_scopes = BTreeMap::new();
170	
171	    for allowed in allowed_commands.values_mut() {
172	      if !allowed.scope.is_empty() {
173	        allowed.scope.sort();
174	
175	        let mut hasher = DefaultHasher::new();
176	        allowed.scope.hash(&mut hasher);
177	        let hash = hasher.finish();
178	
179	        allowed.resolved_scope_key.replace(hash);
180	
181	        let resolved_scope = ResolvedScope {
182	          allow: allowed
183	            .scope
184	            .iter()
185	            .flat_map(|s| command_scopes.get(s).unwrap().allow.clone())
186	            .flatten()
187	            .collect(),
188	          deny: allowed
189	            .scope
190	            .iter()
191	            .flat_map(|s| command_scopes.get(s).unwrap().deny.clone())
192	            .flatten()
193	            .collect(),
194	        };
195	
196	        resolved_scopes.insert(hash, resolved_scope);
197	      }
198	    }
199	
200	    let global_scope = global_scope
201	      .into_iter()
202	      .map(|(key, scopes)| {
203	        let mut resolved_scope = ResolvedScope::default();
204	        for scope in scopes {
205	          if let Some(allow) = scope.allow {
206	            resolved_scope.allow.extend(allow);
207	          }
208	          if let Some(deny) = scope.deny {
209	            resolved_scope.deny.extend(deny);
210	          }
211	        }
212	        (key, resolved_scope)
213	      })
214	      .collect();
215	
216	    let resolved = Self {
217	      allowed_commands: allowed_commands
218	        .into_iter()
219	        .map(|(key, cmd)| {
220	          Ok((
221	            key,
222	            ResolvedCommand {
223	              #[cfg(debug_assertions)]
224	              referenced_by: cmd.referenced_by,
225	              windows: parse_glob_patterns(cmd.windows)?,
226	              webviews: parse_glob_patterns(cmd.webviews)?,
227	              scope: cmd.resolved_scope_key,
228	            },
229	          ))
230	        })
231	        .collect::<Result<_, Error>>()?,
232	      denied
